(() => {
'use strict';
const catalog=window.ROMANZ_PRODUCTS||[],money=n=>'LKR '+n.toLocaleString('en-LK'),key='romanz-bag-v1';let bag=[];
try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))bag=saved.filter(i=>{const p=catalog.find(p=>p.id===i?.id);return p&&p.options.includes(i.option)&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<=10;});}catch{}
function persist(){try{localStorage.setItem(key,JSON.stringify(bag));}catch{toast('Device storage is unavailable. Your bag is available for this page only.');}updateBadge();}
function updateBadge(){document.querySelectorAll('[data-bag-count]').forEach(e=>e.textContent=bag.reduce((s,i)=>s+i.qty,0));}
let timer;function toast(message){const el=document.querySelector('#shop-toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),3500);}
function add(id,option){const p=catalog.find(p=>p.id===id);if(!p||!p.options.includes(option))return;if(bag.filter(i=>i.id===id).reduce((s,i)=>s+i.qty,0)>=p.stock){toast('No more stock available for this sample item.');return;}const existing=bag.find(i=>i.id===id&&i.option===option);if(existing&&existing.qty>=10){toast('Maximum 10 of each size per bag.');return;}if(existing)existing.qty++;else bag.push({id,option,qty:1});persist();toast(`${p.name} added to your bag.`);}
const productLink=p=>'product.html?id='+encodeURIComponent(p.id);
function card(p){return `<article class="shop-card"><a class="shop-photo" href="${productLink(p)}" aria-label="View ${p.name}"><img src="${p.image}" alt="${p.name}" loading="lazy" width="600" height="700"><span class="tag">${p.stock===0?'Sold out':p.tag}</span><span class="view">View details</span></a><p class="product-category">${p.category} · ${p.finish}</p><a href="${productLink(p)}"><h3>${p.name}</h3></a><div class="price-row"><strong>${money(p.price)}</strong><span>Sample price</span></div>${p.stock===0?'<button class="quick-add" disabled>Sold out</button>':p.options.length===1?`<button class="quick-add" data-add="${p.id}">Add to bag <span>+</span></button>`:`<a class="quick-add" href="${productLink(p)}">Choose ${p.category==='necklaces'?'length':'size'} <span>+</span></a>`}</article>`;}
let filter=new URLSearchParams(location.search).get('category')||'all';if(!['all',...catalog.map(p=>p.category)].includes(filter))filter='all';
function renderShop(){const grid=document.querySelector('#shop-grid');if(!grid)return;const q=(document.querySelector('#shop-search').value||'').trim().toLowerCase();let list=catalog.filter(p=>(filter==='all'||p.category===filter)&&`${p.name} ${p.category} ${p.finish}`.toLowerCase().includes(q));const order=document.querySelector('#shop-sort').value;if(order==='price-asc')list.sort((a,b)=>a.price-b.price);if(order==='price-desc')list.sort((a,b)=>b.price-a.price);if(order==='name')list.sort((a,b)=>a.name.localeCompare(b.name));grid.innerHTML=list.map(card).join('');document.querySelector('#count').textContent=`${list.length} of ${catalog.length} pieces`;document.querySelector('#shop-empty').hidden=!!list.length;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter));});}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;renderShop();}));document.querySelector('#shop-search')?.addEventListener('input',renderShop);document.querySelector('#shop-sort')?.addEventListener('change',renderShop);document.querySelector('#reset-filters')?.addEventListener('click',()=>{filter='all';document.querySelector('#shop-search').value='';document.querySelector('#shop-sort').value='featured';renderShop();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b){const p=catalog.find(p=>p.id===b.dataset.add);if(p)add(p.id,p.options[0]);}});
function renderProduct(){const target=document.querySelector('#product-page');if(!target)return;const p=catalog.find(p=>p.id===new URLSearchParams(location.search).get('id'));if(!p){target.innerHTML='<h1>Piece not found</h1><p>This piece is not in the current collection.</p><a class="button" href="collection.html">Shop all jewellery</a>';return;}document.title=p.name+' — ROMANZ Jewellery';target.innerHTML=`<div class="breadcrumb"><a href="index.html">Home</a> / <a href="collection.html">Shop jewellery</a> / ${p.name}</div><div class="product-detail-layout"><img class="detail-photo" src="${p.image}" alt="${p.name}"><div class="detail-content"><p class="eyebrow">${p.category} / THE ROMANZ EDIT</p><h1>${p.name}</h1><p class="detail-price">${money(p.price)} <small>Sample price</small></p><p>${p.description}</p><p class="finish-label">Style: ${p.finish}</p><label class="option-label" for="product-option">${p.category==='rings'?'Ring size':p.category==='bracelets'?'Bracelet length':p.category==='necklaces'?'Necklace length':'Selection'}</label><select id="product-option">${p.options.map(o=>`<option>${o}</option>`).join('')}</select><button id="add-selected" class="button" ${p.stock===0?'disabled':''}>${p.stock===0?'Sold out':'Add to bag'}</button><a class="text-link" href="bag.html">View your bag</a><p class="sample-note">Sample item and imagery. Materials, sizing, stock, and final pricing must be confirmed before launch.</p><details><summary>Styling notes</summary><p>Let this piece stand alone, or combine it with a simple coordinating finish for a look that feels your own.</p></details><details><summary>Care & storage</summary><p>Keep dry and away from perfume. Wipe gently with a soft cloth and store separately. <a href="care.html">Read the care guide.</a></p></details><details><summary>Delivery & returns</summary><p>This is a demo store. Delivery and return policies will be available before real orders are enabled.</p></details></div></div><section class="related"><p class="eyebrow">FINISH YOUR EDIT</p><h2>You might also <em>love.</em></h2><div class="shop-grid">${catalog.filter(x=>x.id!==p.id).slice(0,3).map(card).join('')}</div></section>`;document.querySelector('#add-selected').addEventListener('click',()=>add(p.id,document.querySelector('#product-option').value));}
const subtotal=()=>bag.reduce((s,i)=>s+catalog.find(p=>p.id===i.id).price*i.qty,0);
function renderBag(){const list=document.querySelector('#bag-items');if(!list)return;const summary=document.querySelector('#bag-summary');if(!bag.length){list.innerHTML='<div class="empty-bag"><span>✧</span><h2>Your next favourite awaits.</h2><p>Your shopping bag is empty. Explore the collection and find something that feels like you.</p><a class="button" href="collection.html">Explore jewellery</a></div>';summary.hidden=true;return;}summary.hidden=false;list.innerHTML=bag.map((i,n)=>{const p=catalog.find(p=>p.id===i.id);return `<article class="bag-item"><a href="${productLink(p)}"><img src="${p.image}" alt="${p.name}"></a><div><h3><a href="${productLink(p)}">${p.name}</a></h3><p>${i.option} · ${p.finish}</p><strong>${money(p.price)}</strong><div class="quantity"><button data-qty="${n}" data-step="-1" aria-label="Decrease quantity of ${p.name}" ${i.qty===1?'disabled':''}>−</button><span aria-label="Quantity">${i.qty}</span><button data-qty="${n}" data-step="1" aria-label="Increase quantity of ${p.name}" ${i.qty===10?'disabled':''}>+</button><button class="remove-item" data-remove="${n}" aria-label="Remove ${p.name}">Remove</button></div></div><strong class="line-total">${money(p.price*i.qty)}</strong></article>`;}).join('');summary.innerHTML=`<h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><strong>${money(subtotal())}</strong></div><p>Delivery preview available at checkout. All prices are illustrative.</p><div class="summary-line total"><span>Subtotal</span><strong>${money(subtotal())}</strong></div><a href="checkout.html" class="button">Continue to demo checkout</a><a href="collection.html" class="text-link">Continue shopping</a><p class="sample-note">Demo store · No real orders or payments</p>`;}
document.addEventListener('click',e=>{const q=e.target.closest('[data-qty]'),r=e.target.closest('[data-remove]');if(q){const i=bag[Number(q.dataset.qty)];if(i)i.qty=Math.max(1,Math.min(10,catalog.find(p=>p.id===i.id).stock-bag.filter(x=>x.id===i.id&&x!==i).reduce((s,x)=>s+x.qty,0),i.qty+Number(q.dataset.step)));persist();renderBag();}if(r){bag.splice(Number(r.dataset.remove),1);persist();renderBag();toast('Item removed from your bag.');}});
function renderCheckout(){const summary=document.querySelector('#checkout-summary');if(!summary)return;if(!bag.length){document.querySelector('#checkout-flow').innerHTML='<h2>Your bag is empty</h2><p>Add a favourite piece before exploring checkout.</p><a class="button" href="collection.html">Explore jewellery</a>';summary.hidden=true;return;}const shipping=Number(document.querySelector('[name="delivery"]:checked')?.value||0);summary.innerHTML=`<h2>Your selection</h2>${bag.map(i=>{const p=catalog.find(p=>p.id===i.id);return `<div class="checkout-item"><img src="${p.image}" alt=""><div><strong>${p.name}</strong><small>${i.option} · Qty ${i.qty}</small><span>${money(p.price*i.qty)}</span></div></div>`;}).join('')}<div class="summary-line"><span>Subtotal</span><strong>${money(subtotal())}</strong></div><div class="summary-line"><span>Delivery (sample)</span><strong>${money(shipping)}</strong></div><div class="summary-line total"><span>Demo total</span><strong>${money(subtotal()+shipping)}</strong></div><a class="text-link" href="bag.html">Edit your bag</a>`;}
document.querySelectorAll('[name="delivery"]').forEach(r=>r.addEventListener('change',renderCheckout));document.querySelector('#preview-order')?.addEventListener('click',()=>{if(!bag.length)return;document.querySelector('#checkout-flow').innerHTML='<div class="demo-confirmation" tabindex="-1"><span>✧</span><p class="eyebrow">CHECKOUT PREVIEW COMPLETE</p><h2>A beautiful choice.</h2><p>This is what your confirmation could look like. <strong>No real order has been placed and no payment was taken.</strong></p><p>Your selected pieces are still in your bag.</p><a class="button" href="collection.html">Continue exploring</a><a class="text-link" href="bag.html">Return to bag</a></div>';document.querySelector('.demo-confirmation').focus();});
document.querySelectorAll('nav a').forEach(a=>{if(a.getAttribute('href')===location.pathname.split('/').pop())a.setAttribute('aria-current','page');});const year=document.querySelector('#year');if(year)year.textContent=new Date().getFullYear();updateBadge();renderShop();renderProduct();renderBag();renderCheckout();
})();
